/**
 * What the neglect screen cannot know.
 *
 * The list is generated by scripts/build-screen-assets.mjs from committed
 * benchmark artifacts into screenLimitations.generated.json, and both the page
 * and server/neglectScreen.js read that one file. Nothing here is typed by
 * hand, and nothing here depends on a screen having been run: this panel must
 * render on first paint, because a reader who sees the table without it has
 * been misled about what the table means.
 */
import generated from "./screenLimitations.generated.json";

/** Every limitation, in the order the generator fixed. */
export const SCREEN_LIMITATIONS = generated.limitations;

/**
 * The first entry is the mismatch between an oncology-validated evidence model
 * and a disease burden that is mostly not cancer. It is first deliberately: it
 * is the limitation most likely to bite the screen's intended use.
 */
export const AXIS_MISMATCH_ID = "axis-mismatch";

export function axisMismatchLimitation() {
  return SCREEN_LIMITATIONS.find((l) => l.id === AXIS_MISMATCH_ID) || null;
}

/**
 * EFO/MONDO ids the committed labelling marks non-cancer, carried in the same
 * generated file so the page can warn inline when a run falls outside the
 * range the evidence model was validated on.
 */
export const NON_CANCER_DISEASE_IDS = new Set(generated.nonCancerDiseaseIds || []);

export function isNonCancerDisease(diseaseId) {
  return NON_CANCER_DISEASE_IDS.has(String(diseaseId || ""));
}

/** Structured counts for the inline warning, so no prose is parsed. */
export const VALIDATION_PANEL = generated.validationPanel || {};

export const CANCER_LABELS_SOURCE = generated.cancerLabelsSource || null;

export default SCREEN_LIMITATIONS;
